import React, { useEffect, useState } from "react";
import "../../styles/adminStock.css";
import AddService from "./AddService";

function AdminServices() {
    const [slots, setSlots] = useState([]);
    const [displayedSlots, setDisplayedSlots] = useState([]);
    const [catalog, setCatalog] = useState([]);
    
    const [filterDate, setFilterDate] = useState('');
    const [filterType, setFilterType] = useState('');

    const [showAddForm, setShowAddForm] = useState(false);
    const [participantsParams, setParticipantsParams] = useState(null);
    const [showSuccessDialog, setShowSuccessDialog] = useState(false);

    const fetchData = () => {
        fetch('http://localhost:3001/admin/services')
            .then(res => res.json())
            .then(data => {
                if (Array.isArray(data)) {
                    setSlots(data);
                    setDisplayedSlots(data);
                }
            });
        
        fetch('http://localhost:3001/catalog/services')
            .then(res => res.json())
            .then(data => {
                if (Array.isArray(data)) setCatalog(data);
            });
    };

    useEffect(() => { fetchData(); }, []);

    useEffect(() => {
        let filtered = slots.filter(slot => {
            const slotDateStr = slot.date ? new Date(slot.date).toISOString().split('T')[0] : '';
            const matchDate = filterDate === '' || slotDateStr === filterDate;
            const matchType = filterType === '' || String(slot.idTypeService) === filterType;
            return matchDate && matchType;
        });
        setDisplayedSlots(filtered);
    }, [filterDate, filterType, slots]);

    const onSlotAddedSuccessfully = () => {
        setShowAddForm(false); 
        fetchData();           
        setShowSuccessDialog(true); 
    };

    const handleDeleteSlot = (idService) => {
        if (window.confirm("Supprimer ce créneau ? Toutes les réservations associées seront annulées.")) {
            fetch(`http://localhost:3001/admin/services/${idService}`, { method: 'DELETE' })
            .then(() => fetchData());
        }
    };

    const handleViewParticipants = (idService, slotName) => {
        fetch(`http://localhost:3001/admin/services/${idService}/participants`)
            .then(res => res.json())
            .then(data => {
                setParticipantsParams({ name: slotName, list: data });
            });
    };

    const resetFilters = (e) => {
        e.preventDefault();
        setFilterDate('');
        setFilterType('');
    };

    const formatDateTime = (dateStr, timeStr) => {
        const d = new Date(dateStr);
        const [hours, minutes] = timeStr.split(':');
        d.setHours(parseInt(hours, 10), parseInt(minutes, 10), 0, 0);
        return `${d.toLocaleDateString('fr-FR')} à ${timeStr.substring(0, 5)}`;
    };

    return (
        <div>
            {/* BOÎTE DE DIALOGUE DE SUCCÈS (Modale) */}
            {showSuccessDialog && (
                <div style={{
                    position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, 
                    backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 1000,
                    display: 'flex', justifyContent: 'center', alignItems: 'center'
                }}>
                    <div style={{
                        backgroundColor: 'white', padding: '30px', borderRadius: '12px', 
                        textAlign: 'center', maxWidth: '400px', boxShadow: '0 4px 20px rgba(0,0,0,0.15)'
                    }}>
                        <div style={{ fontSize: '3rem', marginBottom: '10px' }}>✅</div>
                        <h2 style={{ color: '#10b981', margin: '0 0 10px 0' }}>Créneau ajouté !</h2>
                        <p style={{ color: '#4b5563', marginBottom: '25px' }}>
                            La nouvelle session a bien été enregistrée dans l'agenda. Les clients peuvent désormais s'y inscrire.
                        </p>
                        <button 
                            className="admin-btn-add" 
                            onClick={() => setShowSuccessDialog(false)}
                            style={{ width: '100%' }}
                        >
                            Fermer
                        </button>
                    </div>
                </div>
            )}

            <div className="admin-table-header">
                <h3>Gestion de l'Agenda & Réservations</h3>
                {!showAddForm && (
                    <button className="admin-btn-add" onClick={() => setShowAddForm(true)}>
                        + Ajouter un créneau
                    </button>
                )}
            </div>

            {/* --- LE SECRET EST ICI : ON UTILISE UN IF / ELSE TERNAIRE --- */}
            {showAddForm ? (
                // SI ON A CLIQUE SUR AJOUTER : On affiche UNIQUEMENT le formulaire
                <AddService 
                    catalog={catalog} 
                    onSuccess={onSlotAddedSuccessfully} 
                    onCancel={() => setShowAddForm(false)} 
                />
            ) : (
                // SINON : On affiche les filtres et le tableau normal
                <>
                    {/* BARRE DE FILTRES */}
                    <div className="admin-filters-bar">
                        <div className="admin-filter-group">
                            <label>Filtrer par Date :</label>
                            <input type="date" value={filterDate} onChange={(e) => setFilterDate(e.target.value)} className="admin-filter-input" />
                        </div>
                        <div className="admin-filter-group">
                            <label>Filtrer par Prestation :</label>
                            <select value={filterType} onChange={(e) => setFilterType(e.target.value)} className="admin-filter-input">
                                <option value="">Toutes les prestations</option>
                                {catalog.map(c => <option key={c.idTypeService} value={c.idTypeService}>{c.name}</option>)}
                            </select>
                        </div>
                        <button className="admin-btn-reset" onClick={resetFilters}>Réinitialiser</button>
                    </div>

                    {/* LISTE DES INSCRITS */}
                    {participantsParams && (
                        <div style={{ backgroundColor: '#f0f9fa', padding: '20px', borderRadius: '8px', border: '1px solid #48A3AE', marginBottom: '20px' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <h4 style={{ color: '#00796b', margin: 0 }}>👥 Réservations pour : {participantsParams.name}</h4>
                                <button onClick={() => setParticipantsParams(null)} style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '1.2rem' }}>❌</button>
                            </div>
                            {participantsParams.list.length === 0 ? (
                                <p style={{ marginTop: '15px', fontStyle: 'italic' }}>Personne n'est encore inscrit à cette session.</p>
                            ) : (
                                <ul style={{ marginTop: '15px', lineHeight: '1.8' }}>
                                    {participantsParams.list.map(p => (
                                        <li key={p.idUser}>
                                            <strong>{p.firstName} {p.lastName}</strong> - {p.email} - 📞 {p.phoneNumber || 'Non renseigné'}
                                        </li>
                                    ))}
                                </ul>
                            )}
                        </div>
                    )}

                    {/* TABLEAU DES CRÉNEAUX */}
                    <div className="table-responsive">
                        <table className="admin-table">
                            <thead>
                                <tr>
                                    <th>ID</th>
                                    <th>Prestation</th>
                                    <th>Date & Heure</th>
                                    <th>Durée</th>
                                    <th>Tarif</th>
                                    <th>Remplissage</th>
                                    <th>Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {displayedSlots.map(slot => {
                                    const isFull = slot.inscrits >= slot.numberParticipants;
                                    return (
                                        <tr key={slot.idService}>
                                            <td>#{slot.idService}</td>
                                            <td className="admin-table-name">{slot.typeName}</td>
                                            <td>{formatDateTime(slot.date, slot.heure)}</td>
                                            <td>{slot.duree} min</td>
                                            <td>{Number(slot.price).toFixed(2)} €</td>
                                            <td>
                                                <span className={`stock-badge ${isFull ? 'out-of-stock' : 'in-stock'}`}>
                                                    {slot.inscrits} / {slot.numberParticipants}
                                                </span>
                                            </td>
                                            <td style={{ minWidth: '100px' }}>
                                                <button 
                                                    className="action-btn edit-btn" 
                                                    onClick={() => handleViewParticipants(slot.idService, `${slot.typeName} le ${formatDateTime(slot.date, slot.heure)}`)}
                                                    title="Voir les inscrits"
                                                >
                                                    👁️
                                                </button>
                                                <button 
                                                    className="action-btn delete-btn" 
                                                    onClick={() => handleDeleteSlot(slot.idService)}
                                                    title="Supprimer la session"
                                                    style={{ color: '#e74c3c' }}
                                                >
                                                    🗑️
                                                </button>
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                    </div>
                </>
            )}
        </div>
    );
}

export default AdminServices;
